[
  {
    "id": "home-seeded-packs-declared",
    "severity": "blocking",
    "failureMessage": "baselining lands a seeded pack on every member but is gated !isHome, so a newly seeded pack reaches the whole fleet except this repo, invisibly",
    "scanIgnoringComments": true,
    "requireIndexCoverage": [
      {
        "eachTrackedPathMatching": "/^packs\\/(?<pack>[^/]+)\\/pack\\.mjs$/",
        "whoseTextMatches": "/(^|[^\\w.$])seededByDefault\\s*:\\s*true\\b/",
        "indexFile": ".claudinite-settings.json",
        "coveredByValueInArrayAtField": {
          "atField": "packs",
          "value": "{pack}",
          "matchingEntryObjectsByField": "id"
        },
        "whenIndexFileAbsent": "assertNothing",
        "anchorFindingsAt": "indexFile",
        "what": "the \"{pack}\" pack flags seededByDefault (packs/{pack}/pack.mjs) but is not declared here",
        "fix": "add \"{pack}\" to the \"packs\" array — baselining skips the home, so this repo's declaration is hand-maintained; a deliberate opt-out is an acceptance with a reason instead"
      }
    ]
  },
  {
    "id": "legacy-tolerance-scheduled",
    "severity": "blocking",
    "since": "2026-09-03",
    "failureMessage": "a legacy tolerance nobody is scheduled to remove is a permanent feature wearing a temporary name, and its holders are never told to move off it",
    "scanFiles": "/^(engine|packs)\\/.*\\.mjs$/",
    "excludeFileClasses": [
      "testFiles"
    ],
    "matchLines": [
      {
        "match": "/^(?:export\\s+)?(?:const|let|function|async function)\\s+\\w*(?:LEGACY|Legacy)\\w*/",
        "unlessPreviousLineMatches": "/@legacy-tolerance/",
        "what": "{match} declares a legacy tolerance with no scheduled removal above it",
        "fix": "put `// @legacy-tolerance advisory:<rule-id|none> retire:#<issue>` directly above it: the rule that tells a holder to migrate, and the issue whose merge deletes this code"
      },
      {
        "match": "/@legacy-tolerance/",
        "unlessLineMatches": "/@legacy-tolerance advisory:(?:[a-z][a-z0-9/-]*) retire:#\\d+$/",
        "what": "{match} is not a readable tolerance annotation",
        "fix": "write it as `// @legacy-tolerance advisory:<rule-id|none> retire:#<issue>` with nothing after — a grep for this token is the register, and an unparseable form is not in it"
      }
    ]
  },
  {
    "id": "rules-append-only",
    "severity": "advisory",
    "scope": "work",
    "failureMessage": "a pack's RULES.md is written several times a day, and a whole-file re-apply onto a moved main deletes lessons with nothing going red",
    "forbidRemovedLinesMatching": [
      {
        "inFilesMatching": "/(^|\\/)packs\\/[^/]+\\/RULES\\.md$/",
        "match": "/^- \\*\\*(?<title>[^*]+)\\*\\*/",
        "unlessMatchRemainsInFile": true,
        "what": "removes the rule \"{title}\"",
        "fix": "re-apply your edit onto the fetched file as an insertion, and say in the PR when a rule is deliberately retired"
      }
    ]
  },
  {
    "id": "git-pull-on-shallow-clone",
    "severity": "blocking",
    "since": "2026-09-06",
    "scope": "action",
    "failureMessage": "the clones here are shallow, so git pull finds no common ancestor, and nothing of value is ever on this repo's local main",
    "guardToolCalls": [
      {
        "tool": "Bash",
        "inputField": "command",
        "match": "/(^|[;&|]\\s*|\\n\\s*)git\\s+pull\\b/",
        "what": "a git pull",
        "fix": "git fetch origin main && git reset --hard origin/main"
      }
    ]
  },
  {
    "id": "merge-main-into-branch",
    "severity": "blocking",
    "since": "2026-09-06",
    "scope": "action",
    "failureMessage": "a merge commit trips the blocking squash-merge-history check; the branch re-verifies against a moved main by rebasing",
    "guardToolCalls": [
      {
        "tool": "Bash",
        "inputField": "command",
        "match": "/(^|[;&|]\\s*|\\n\\s*)git\\s+merge\\s+(origin\\/)?(main|master)\\b/",
        "what": "a merge of main into the branch",
        "fix": "git rebase origin/main"
      }
    ]
  },
  {
    "id": "github-api-via-shell",
    "severity": "blocking",
    "since": "2026-09-06",
    "scope": "action",
    "failureMessage": "there is no gh CLI here, and every repo-scoped api.github.com call 403s (\"GitHub access is not enabled for this session\"), so a shell poll reports \"still running\" until it times out",
    "guardToolCalls": [
      {
        "tool": "Bash",
        "inputField": "command",
        "match": "/(^|[;&|]\\s*|\\n\\s*)((do|then|else)\\s+)?((curl|wget)\\b[^;&|\\n]*api\\.github\\.com|gh\\s)/",
        "what": "a GitHub read through the shell: \"{match}\"",
        "fix": "read the head sha's check runs with the GitHub MCP tools (pull_request_read get_check_runs, get_check_run)"
      },
      {
        "tool": "Monitor",
        "inputField": "command",
        "match": "/(^|[;&|]\\s*|\\n\\s*)((do|then|else)\\s+)?((curl|wget)\\b[^;&|\\n]*api\\.github\\.com|gh\\s)/",
        "what": "a Monitor polling GitHub through the shell: \"{match}\"",
        "fix": "read the head sha's check runs with the GitHub MCP tools on a rolling backoff; a shell poll here never sees the run finish"
      }
    ]
  },
  {
    "id": "bare-sleep-wait",
    "severity": "advisory",
    "scope": "action",
    "failureMessage": "a padded sleep waits on nothing nameable; a guard that would not stand as the whole test is sleeping and calling it polling",
    "fix": "name the condition awaited — a run's status, a file's arrival, a deadline — and wait on that",
    "guardToolCalls": [
      {
        "tool": "Bash",
        "inputField": "command",
        "match": "/(^|[;&|]\\s*)sleep\\s+\\d+\\s*($|[;&|])/",
        "what": "a bare \"{match}\""
      },
      {
        "tool": "Bash",
        "inputField": "command",
        "match": "/\\bfor\\b[^;\\n]*;\\s*do\\s+sleep\\s+\\d+\\s*;\\s*done\\b/",
        "what": "a counted loop with nothing but a sleep in its body: \"{match}\""
      }
    ]
  },
  {
    "id": "test-suite-command-form",
    "severity": "advisory",
    "scope": "action",
    "failureMessage": "a bash glob without globstar reached 37 of 65 files and said nothing; node --test <dir> at least fails outright with Cannot find module",
    "fix": "node --test $(git ls-files '*.test.mjs')",
    "guardToolCalls": [
      {
        "tool": "Bash",
        "inputField": "command",
        "match": "/\\bnode\\s+--test\\s+[^\\s;&|]*\\*/",
        "unlessMatches": "/git ls-files/",
        "what": "the suite run through a glob: \"{match}\""
      },
      {
        "tool": "Bash",
        "inputField": "command",
        "match": "/\\bnode\\s+--test\\s*($|[;&|>])/",
        "what": "node --test with no files named"
      }
    ]
  },
  {
    "id": "commit-all-sweeps-edits",
    "severity": "advisory",
    "scope": "action",
    "failureMessage": "git commit -a stages every modified file, and a later branch -D discards the in-progress edits it swept up",
    "guardToolCalls": [
      {
        "tool": "Bash",
        "inputField": "command",
        "match": "/(^|[;&|]\\s*|\\n\\s*)git\\s+commit\\b[^;&|\\n]*\\s-a(m)?\\b/",
        "what": "a commit with -a",
        "fix": "stage the files this commit is about by name; isolate pending edits first"
      }
    ]
  },
  {
    "id": "ask-user-question-cost",
    "severity": "advisory",
    "scope": "action",
    "failureMessage": "AskUserQuestion blocks about 170 seconds, so it is spent only on a fork that cannot be taken back",
    "guardToolCalls": [
      {
        "tool": "AskUserQuestion",
        "inputMatches": "/./",
        "what": "an AskUserQuestion about to block the session",
        "fix": "if the instruction, the tree or a reversible default answers it, act and say what you assumed instead"
      }
    ]
  },
  {
    "id": "hook-judges-never-exit",
    "severity": "blocking",
    "since": "2026-09-05",
    "failureMessage": "a hook is a guest in the harness: the runner alone exits or writes, and a judge that does prints an error on every call",
    "fix": "return the verdict — { block, reason } or { context } — and let hook-runner.mjs write it",
    "scanFiles": "/^engine\\/hooks\\/[^/]+-judge\\.mjs$/",
    "scanIgnoringComments": true,
    "matchLines": [
      {
        "match": "/\\bprocess\\.(exit|stdout|stderr|stdin)\\b/",
        "what": "a judge touching the process itself: {match}"
      }
    ]
  },
  {
    "id": "migration-record-in-docs",
    "severity": "blocking",
    "since": "2026-09-06",
    "failureMessage": "a migration's plan, status and remaining work live in its tracking issue, never a MIGRATION.md beside the design",
    "forbidTrackedPathsMatching": [
      {
        "match": "/(^|\\/)docs\\/.*MIGRATION\\.md$/",
        "what": "a MIGRATION.md beside a design: {path}",
        "fix": "move what is still live into the tracking issue (writing-migration-plans) and delete the file"
      }
    ]
  },
  {
    "id": "cross-repo-verify-line",
    "severity": "advisory",
    "scope": "action",
    "since": "2026-09-06",
    "failureMessage": "the executor reads only this repository: its sessions carry no member's scope and its probes fetch anonymously, so this verification can never pass",
    "guardToolCalls": [
      {
        "tool": "mcp__github__issue_write",
        "inputField": "body",
        "match": "/^(Verify|In-production-when):[^\\n]*\\bmissingbulb\\/(?!Claudinite\\b)[\\w.-]+/m",
        "what": "a verification line reading another repository: \"{match}\"",
        "fix": "reproduce the premise on an object this repo owns, or file the verification on that repo"
      },
      {
        "tool": "mcp__github__issue_write",
        "inputField": "body",
        "match": "/^(Live-probe|Verify-probe):[^\\n]*api\\.github\\.com/m",
        "what": "a probe fetching the GitHub API: \"{match}\"",
        "fix": "probe a public raw or Pages URL instead, or make it a Verify: line about this repository"
      }
    ]
  },
  {
    "id": "add-repo-for-a-public-clone",
    "severity": "advisory",
    "scope": "action",
    "since": "2026-09-06",
    "failureMessage": "add_repo attaches nothing the git proxy does not already serve for a public repository",
    "guardToolCalls": [
      {
        "tool": "mcp__Claude_Code_Remote__add_repo",
        "inputField": "repo",
        "match": "/./",
        "what": "an add_repo for \"{field}\"",
        "fix": "for a public repository's files, git clone --depth 1 (about two seconds); add_repo only for a private one, or for its issues and pull requests"
      }
    ]
  },
  {
    "id": "scratch-screenshot-caption",
    "severity": "advisory",
    "scope": "action",
    "since": "2026-09-06",
    "failureMessage": "an image rendered from a scratch harness reads as the product unless its caption says otherwise",
    "guardToolCalls": [
      {
        "tool": "SendUserFile",
        "inputMatches": "/scratchpad[^\"]*\\.(png|jpe?g|gif|webp|svg)\\b/i",
        "unlessInputMatches": "/\"caption\":\"[^\"]*(harness|scratch)/i",
        "what": "a screenshot from the scratchpad sent without saying it came from a scratch harness",
        "fix": "say in the caption that it is rendered from a scratch test harness, not just what the widget shows"
      }
    ]
  },
  {
    "id": "author-association-as-permission",
    "severity": "blocking",
    "since": "2026-09-06",
    "failureMessage": "MEMBER covers any org member and COLLABORATOR includes read-only ones, both broader than push access",
    "scanFiles": "/\\.mjs$/",
    "excludeFiles": "/(^|\\/)(test|tests|fixtures|engine-tests)\\/|\\.test\\.mjs$/",
    "scanIgnoringComments": true,
    "matchLines": [
      {
        "match": "/\\bauthor_association\\b/",
        "what": "reads author_association: {match}",
        "fix": "read the collaborators permission endpoint (GET /repos/../collaborators/../permission) for the actor instead"
      }
    ]
  },
  {
    "id": "updates-export-removed",
    "severity": "blocking",
    "scope": "work",
    "since": "2026-09-06",
    "failureMessage": "fielded workers are stale callers of an instantly-current flow module, so a removed export wedges every member on its next run",
    "forbidRemovedLinesMatching": [
      {
        "inFilesMatching": "/^(updates|packs\\/claudinite-lifecycle\\/updates)\\/[^/]+\\.mjs$/",
        "match": "/^export\\s+(async\\s+)?(function|const|let|class)\\s+\\w+|^export\\s*\\{|^export\\s+\\*/",
        "unlessMatchRemainsInFile": true,
        "what": "removes an export from a fielded flow module: {match}",
        "fix": "empty the export instead, and say at its definition why it stays"
      }
    ]
  },
  {
    "id": "year-last-digit-rollover",
    "severity": "blocking",
    "since": "2026-09-06",
    "failureMessage": "a year's last digit wraps to 0 in 2030, so an identifier anchored on it collides four years out",
    "scanFiles": "/\\.mjs$/",
    "excludeFiles": "/(^|\\/)(test|tests|fixtures|engine-tests)\\/|\\.test\\.mjs$/",
    "scanIgnoringComments": true,
    "matchLines": [
      {
        "match": "/\\b\\w*[yY]ear\\w*\\s*%\\s*10\\b/",
        "what": "anchors a year on its last digit: {match}",
        "fix": "subtract an epoch (year - 2020) so the encoding survives the decade boundary"
      }
    ]
  },
  {
    "id": "checkout-restores-index",
    "severity": "advisory",
    "scope": "action",
    "since": "2026-09-06",
    "failureMessage": "git checkout -- restores from the index, destroying uncommitted work as thoroughly as the mutation it undoes",
    "guardToolCalls": [
      {
        "tool": "Bash",
        "inputField": "command",
        "match": "/(^|[;&|]\\s*|\\n\\s*)git\\s+(checkout\\s+--|restore\\s|stash\\b)/",
        "what": "a working-tree restore: \"{match}\"",
        "fix": "commit or stage the real edit first, and only mutate a file whose current state you are ready to throw away"
      }
    ]
  },
  {
    "id": "settings-json-reserialized",
    "severity": "advisory",
    "scope": "action",
    "since": "2026-09-06",
    "failureMessage": "a JSON round trip rewrites indent, key order and escapes while nothing fails and tests stay green",
    "guardToolCalls": [
      {
        "tool": "Bash",
        "inputField": "command",
        "match": "/JSON\\.stringify\\([^\\n]*\\.claudinite-settings\\.json|\\.claudinite-settings\\.json[^\\n]*JSON\\.stringify|json\\.dump\\([^\\n]*settings|settings[^\\n]*json\\.dump\\(/",
        "what": "a settings file rewritten by re-serialising it: \"{match}\"",
        "fix": "patch the file as anchored text instead"
      }
    ]
  },
  {
    "id": "design-doc-status-banner",
    "severity": "advisory",
    "since": "2026-09-08",
    "failureMessage": "an initiative's DESIGN.md reads as a description of how the system works; without a status on its first screen a reader takes an unbuilt proposal for the current state",
    "scanFiles": "/(^|\\/)docs\\/[^/]+\\/DESIGN\\.md$/",
    "scanTracked": true,
    "checkEachFile": [
      {
        "require": "/^(?:.*\\n){0,6}> \\*\\*Status: (?:not implemented|in flight)\\.\\*\\* /",
        "what": "carries no status banner in its first seven lines",
        "fix": "open it with `> **Status: not implemented.** \u2026` or `> **Status: in flight.** \u2026`; a built system's design doc has no third status \u2014 delete it whole instead"
      }
    ]
  },
  {
    "id": "busy-wait-loop",
    "severity": "blocking",
    "since": "2026-09-11",
    "scope": "action",
    "failureMessage": "a loop body of `:` yields nothing, so the shell spins at full tilt and the session answers nobody until a person interrupts it",
    "guardToolCalls": [
      {
        "tool": "Bash",
        "inputField": "command",
        "match": "/(^|[;&|]\\s*|\\n\\s*)(until|while)\\b[^\\n]*;\\s*do\\s*(:|true)\\s*;\\s*done\\b/",
        "what": "a loop that spins without waiting: \"{match}\"",
        "fix": "sleep inside the loop body and bound the wait \u2014 or drop the loop: a background task's completion arrives as a notification"
      }
    ]
  }
]

