  assert.deepEqual(judge('commit-all-sweeps-edits', ['git commit -am "probe"', 'git commit -m "real" -- a.mjs']), ['a commit with -a']);
  const rule = declaredCheck('.claudinite/local/packs/claudinite', 'ask-user-question-cost');
